/* Conector inicial: Auth real e consultas de diagnóstico. Sem escrita/migração de dados. */
(function(root,factory){if(typeof module==='object')module.exports=factory();else root.MartinsSupabaseConexao=factory();})(globalThis,()=>{'use strict';
const TABLES=['martins_auditoria','martins_depositos','martins_empresas','martins_movimentos_estoque','martins_notas_compra','martins_perfis','martins_precos_compra','martins_produtos','martins_unidades'];
const uuid=v=>typeof v==='string'&&/^[a-f\d]{8}-(?:[a-f\d]{4}-){3}[a-f\d]{12}$/i.test(v);
function config(input){let url;try{url=new URL(String(input.url).trim());}catch{throw Error('Informe a Project URL do Supabase');}if(url.protocol!=='https:'||!url.hostname.match(/^[a-z0-9]{10,40}\.supabase\.co$/)||url.username||url.password||url.port||url.search||url.hash||url.pathname!=='/')throw Error('Use somente a URL HTTPS original do projeto Supabase, sem caminho ou parâmetros');const key=String(input.key||'').trim();if(!/^sb_publishable_[a-zA-Z0-9_-]{16,200}$/.test(key))throw Error('Use somente Publishable Key (sb_publishable_). Chave secreta, service_role ou JWT não são aceitos.');return {url:url.origin,key};}
function create(input,{fetcher=globalThis.fetch,now=()=>Date.now(),timeoutMs=15000}={}){const cfg=config(input);let epoch=0,session=null,company=null,profiles=[];const controllers=new Set;
function clear(){epoch++;for(const c of controllers)c.abort();controllers.clear();session=null;company=null;profiles=[];}
function current(e){if(e!==epoch)throw Error('Operação encerrada ou substituída; resultado descartado');}
function token(){if(!session||session.expiresAt<=now()+5000){clear();throw Error('Sessão ausente ou expirada. Faça login novamente.');}return session.accessToken;}
async function request(path,{method='GET',body,accessToken,op=epoch}={}){const allowed=method==='GET'&&(path==='/auth/v1/user'||path.startsWith('/rest/v1/'))||method==='POST'&&['/auth/v1/token?grant_type=password','/auth/v1/logout?scope=local','/rest/v1/rpc/martins_empresa_autorizada'].includes(path);if(!allowed)throw Error('Operação fora do diagnóstico permitido');current(op);const control=new AbortController();controllers.add(control);const timer=setTimeout(()=>control.abort(),timeoutMs);try{const headers={apikey:cfg.key,Accept:'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(accessToken)headers.Authorization='Bearer '+accessToken;const r=await fetcher(cfg.url+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),signal:control.signal,credentials:'omit',cache:'no-store',redirect:'error',referrerPolicy:'no-referrer'});current(op);if(!r.ok){const error=Error('Requisição recusada pelo Supabase (HTTP '+r.status+'). Confira conexão, credenciais, permissões e esquema.');error.status=r.status;throw error;}if(r.status===204)return null;const result=await r.json();current(op);return result;}catch(e){if(op!==epoch)throw Error('Operação encerrada ou substituída; resultado descartado');if(e.status)throw e;throw Error(e.name==='AbortError'?'Tempo limite da conexão atingido; nenhuma gravação de dados foi enviada.':'Falha de conexão ou resposta inválida. Confira o projeto e a disponibilidade da rede.');}finally{clearTimeout(timer);controllers.delete(control);}}
async function ownProfiles(op){const accessToken=token(),id=session.user.id,result=await request('/rest/v1/martins_perfis?select=usuario_id,empresa_id,ativo,papel&usuario_id=eq.'+encodeURIComponent(id),{accessToken,op});if(!Array.isArray(result))throw Error('Resposta inválida do cadastro de perfis');const seen=new Set;for(const p of result){if(!p||p.usuario_id!==id||!uuid(p.empresa_id)||typeof p.ativo!=='boolean'||typeof p.papel!=='string'||seen.has(p.empresa_id))throw Error('Perfis inconsistentes ou ambíguos. Nenhuma empresa foi autorizada.');seen.add(p.empresa_id);}return result;}
async function signIn(email,password){clear();const op=epoch;if(typeof email!=='string'||!email.trim()||typeof password!=='string'||!password)throw Error('Informe e-mail e senha do Supabase Auth');try{const signed=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email:email.trim(),password},op});if(typeof signed?.access_token!=='string'||!signed.access_token||!Number.isFinite(signed.expires_in)||signed.expires_in<=10)throw Error('Resposta de autenticação inválida');const user=await request('/auth/v1/user',{accessToken:signed.access_token,op});if(!uuid(user?.id)||signed.user?.id&&signed.user.id!==user.id)throw Error('Identidade não confirmada pelo servidor');current(op);session={accessToken:signed.access_token,expiresAt:now()+signed.expires_in*1000,user:{id:user.id,email:user.email||email.trim()}};profiles=await ownProfiles(op);current(op);return {user:{...session.user},profiles:structuredClone(profiles),expiresAt:session.expiresAt};}catch(e){if(op===epoch)clear();throw e;}finally{password='';}}
async function authorize(id){company=null;const op=epoch;token();if(!uuid(id))throw Error('Empresa inválida');const fresh=await ownProfiles(op),profile=fresh.find(p=>p.empresa_id===id&&p.ativo&&p.papel==='administrador');if(!profile)throw Error('Perfil ativo de administrador não confirmado para esta empresa');const allowed=await request('/rest/v1/rpc/martins_empresa_autorizada',{method:'POST',body:{p_empresa:id},accessToken:token(),op});if(allowed!==true)throw Error('A função de autorização não liberou esta empresa');current(op);profiles=fresh;company=id;return {empresaId:id,papel:profile.papel};}
async function diagnose(){if(!company)throw Error('Selecione e autorize uma empresa antes de consultar');const id=company,op=epoch;await authorize(id);const results=[];for(const table of TABLES){current(op);if(company!==id)throw Error('Empresa alterada durante a consulta');try{const rows=await request('/rest/v1/'+table+'?select=*&limit=0',{accessToken:token(),op});if(!Array.isArray(rows)||rows.length)throw Error('Resposta inesperada');results.push({tabela:table,status:'Consulta sem linhas aceita',ok:true});}catch(e){current(op);if(!session)throw e;results.push({tabela:table,status:e.status?'HTTP '+e.status:e.message,ok:false});}}return {empresaId:id,results,rlsCompleta:false,observacao:'LIMIT 0 verifica acesso à tabela/API, não isolamento de linhas nem permissão de escrita. Nenhuma linha de negócio foi carregada.'};}
async function negative(id){if(!company)throw Error('Autorize uma empresa primeiro');if(!uuid(id)||id===company)throw Error('Informe uma empresa de controle diferente da autorizada');const own=await ownProfiles(epoch);if(own.some(p=>p.empresa_id===id))throw Error('Empresa de controle tem vínculo com este usuário');const result=await request('/rest/v1/rpc/martins_empresa_autorizada',{method:'POST',body:{p_empresa:id},accessToken:token()});if(result!==false){company=null;throw Error('Falha de segurança: autorização não retornou false para a empresa sem vínculo. Consultas suspensas.');}return {negado:true,observacao:'Função negou a empresa de controle sem vínculo. Isto não homologa todas as políticas RLS.'};}
async function signOut(){const accessToken=session?.accessToken;clear();if(!accessToken)return {local:true,servidor:false};try{await request('/auth/v1/logout?scope=local',{method:'POST',accessToken});return {local:true,servidor:true};}catch{return {local:true,servidor:false};}}
function state(){return {autenticado:Boolean(session&&session.expiresAt>now()+5000),empresaId:company,user:session?{...session.user}:null};}
return {signIn,authorize,diagnose,negative,signOut,disconnect:clear,state};}
return {TABLES,uuid,config,create};});
